# --- 스레드 이름과 함께 찍는다 ---

@GetMapping("/ctx")
@ResponseBody
public String ctx() throws Exception {
    System.out.println(">>> [" + Thread.currentThread().getName() + "] "
            + SecurityContextHolder.getContext().getAuthentication());

    Thread t = new Thread(() -> System.out.println(">>> ["
            + Thread.currentThread().getName() + "] "
            + SecurityContextHolder.getContext().getAuthentication()));
    t.start();
    t.join();
    return "ok";
}

$ curl -s -b c.txt localhost:8080/ctx

>>> [http-nio-8080-exec-1] UsernamePasswordAuthenticationToken
     [Principal=User [Username=user], Authenticated=true]
>>> [Thread-5] null

#   같은 요청 안인데 다른 스레드는 null 이다

#   ThreadLocal 이라서다

# --- 전략을 바꾼다 ---

@PostConstruct
void init() {
    SecurityContextHolder.setStrategyName(
            SecurityContextHolder.MODE_INHERITABLETHREADLOCAL);
}

$ curl -s -b c.txt localhost:8080/ctx

>>> [http-nio-8080-exec-1] UsernamePasswordAuthenticationToken [...user...]
>>> [Thread-5] UsernamePasswordAuthenticationToken [...user...]

#   물려받았다

# --- 스레드 풀에서는 ---

private final ExecutorService pool = Executors.newFixedThreadPool(1);

@GetMapping("/pool")
@ResponseBody
public String pool() throws Exception {
    Authentication here = SecurityContextHolder.getContext().getAuthentication();
    Future<String> f = pool.submit(() -> {
        Authentication there = SecurityContextHolder.getContext()
                .getAuthentication();
        return Thread.currentThread().getName() + " -> "
                + (there == null ? "null" : there.getName());
    });
    System.out.println(">>> here  = " + here.getName());
    System.out.println(">>> there = " + f.get());
    return "ok";
}

#   user 로 로그인해 부른다
$ curl -s -b user.txt localhost:8080/pool

>>> here  = user
>>> there = pool-1-thread-1 -> user

#   INHERITABLE 이라 물려받았다

#   admin 으로 로그인해 부른다
$ curl -s -b admin.txt localhost:8080/pool

>>> here  = admin
>>> there = pool-1-thread-1 -> user

#   admin 이 부른 작업이 user 로 돈다

#   풀 스레드는 처음 만들 때 한 번 물려받고 끝이다

#   이게 INHERITABLE 의 함정이다

# --- 감싼 실행기를 쓴다 ---

private final ExecutorService pool =
        new DelegatingSecurityContextExecutorService(
                Executors.newFixedThreadPool(1));

$ curl -s -b user.txt localhost:8080/pool
>>> there = pool-1-thread-1 -> user

$ curl -s -b admin.txt localhost:8080/pool
>>> there = pool-1-thread-1 -> admin

#   이번엔 맞다

#   제출할 때의 컨텍스트를 실어 나른다

# --- 요청이 끝나면 비워지나 ---

@Component
public class TailFilter extends OncePerRequestFilter {
    @Override
    protected void doFilterInternal(HttpServletRequest req,
            HttpServletResponse res, FilterChain chain)
            throws ServletException, IOException {
        chain.doFilter(req, res);
        System.out.println(">>> after chain ["
                + Thread.currentThread().getName() + "] "
                + SecurityContextHolder.getContext().getAuthentication());
    }
}

#   (security 필터보다 앞에 등록되게 order 를 -200 으로 준다)

$ curl -s -b c.txt localhost:8080/orders -o /dev/null

>>> after chain [http-nio-8080-exec-1] null

#   FilterChainProxy 를 빠져나오면 비어 있다

TRACE FilterChainProxy : Invoking SecurityContextHolderFilter (3/14)
DEBUG SecurityContextHolderFilter : Retrieved SecurityContextImpl [...]
TRACE FilterChainProxy : Invoking AuthorizationFilter (14/14)
DEBUG FilterChainProxy : Secured GET /orders

#   3번이 채우고 finally 가 비운다

# --- 안 비우면 어떻게 되나 ---

#   (홀더를 요청 밖에서 직접 채워 본다)

@Component
public class LeakFilter extends OncePerRequestFilter {
    protected void doFilterInternal(...) {
        SecurityContextHolder.getContext().setAuthentication(
                UsernamePasswordAuthenticationToken.authenticated(
                        "leaked", null, List.of()));
        chain.doFilter(req, res);
        // clearContext 를 안 부른다
    }
}

$ curl -s localhost:8080/ctx
>>> [http-nio-8080-exec-1] ... Principal=leaked ...

$ curl -s localhost:8080/ctx
>>> [http-nio-8080-exec-2] ... Principal=leaked ...

#   (톰캣 스레드가 8개라 몇 번 부르면 도는데)

#   같은 스레드가 재사용되면 남의 신분이 남는다

#   FilterChainProxy 의 finally 가 이걸 막는다

